//! Table tests of the CLASS a producer gives its collection, for the producers a node holds generic
//! where a constant, a box's own byte fields and a header's are specialised: a collection
//! expression in a register or a context variable, R1, R2 and R3's bytes read as registers, the
//! pre-header's `parentId` and `votes`. The class shows wherever an operation reads through its
//! receiver's class: `getOrElse` and `ByIndex` with a default of another class, `startsWith`,
//! `endsWith` and `patch` with a collection held over another array give a value on a generic
//! receiver. The rows are sigma-state 6.0.7's at activated version 3, in contexts whose boxes and
//! extensions are read from the probes' bytes (queue item 31's `measure/`, generated by
//! `measure/tests/gen_ctx_rows_test.py`)
use crate::eval::test_util::jvm_text;
use crate::eval::{Env, Evaluable};
use ergotree_ir::chain::context::arbitrary::DummyContextExtensionProvider;
use ergotree_ir::chain::context::{Context, TxIoVec};
use ergotree_ir::chain::context_extension::ContextExtension;
use ergotree_ir::chain::ergo_box::{ErgoBox, ErgoBoxCandidate};
use ergotree_ir::chain::tx_id::TxId;
use ergotree_ir::ergo_tree::ErgoTreeVersion;
use ergotree_ir::mir::expr::Expr;
use ergotree_ir::serialization::sigma_byte_reader::{from_bytes, SigmaByteRead};
use ergotree_ir::serialization::SigmaSerializable;
use sigma_test_util::force_any_val;

/// A row: its name in the round's row sets, the expression's bytes, the tree version, what the jars
/// answer (`VALUE`, `ERR`, or the value's text as `jvm_text` prints it), and the cost counter
type Row = (&'static str, &'static str, u8, &'static str, u64);

/// A context whose extension and self box are read from bytes, as a node reads them
#[allow(clippy::unwrap_used)]
fn context(ext_hex: &str, self_hex: &str) -> Context<'static> {
    let v3 = ErgoTreeVersion::V3;
    let self_bytes = base16::decode(self_hex.as_bytes()).unwrap();
    let self_box: ErgoBox = from_bytes(&self_bytes)
        .with_versions(v3, v3, ErgoBox::sigma_parse)
        .unwrap();
    let ext_bytes = base16::decode(ext_hex.as_bytes()).unwrap();
    let ext: ContextExtension = from_bytes(&ext_bytes)
        .with_versions(v3, v3, ContextExtension::sigma_parse)
        .unwrap();
    let mut ctx = force_any_val::<Context>();
    ctx.self_box = alloc::boxed::Box::leak(alloc::boxed::Box::new(self_box));
    ctx.extension = alloc::boxed::Box::leak(alloc::boxed::Box::new(ext));
    ctx.activated_script_version_byte = 3;
    ctx
}

/// The bytes of a spend: SELF and a second input with their extensions, a data input, the output
/// candidates, and the transaction's id
struct TxBytes {
    self_box: &'static str,
    ext: &'static str,
    in1: &'static str,
    ext1: &'static str,
    data: &'static str,
    outs: &'static [&'static str],
    tx_id: &'static str,
}

/// A context whose boxes and extensions are all read from bytes, as a node reads a transaction's:
/// two inputs (SELF the first), one data input, and the outputs built from their candidates
#[allow(clippy::unwrap_used)]
fn tx_context(tx: &TxBytes) -> Context<'static> {
    fn leak<T>(t: T) -> &'static T {
        alloc::boxed::Box::leak(alloc::boxed::Box::new(t))
    }
    let v3 = ErgoTreeVersion::V3;
    let hex = |h: &str| base16::decode(h.as_bytes()).unwrap();
    let read_box = |h: &str| -> &'static ErgoBox {
        leak(
            from_bytes(&hex(h))
                .with_versions(v3, v3, ErgoBox::sigma_parse)
                .unwrap(),
        )
    };
    let read_ext = |h: &str| -> ContextExtension {
        from_bytes(&hex(h))
            .with_versions(v3, v3, ContextExtension::sigma_parse)
            .unwrap()
    };
    let tx_id = TxId(ergo_chain_types::Digest32::try_from(&hex(tx.tx_id)[..]).unwrap());
    let outs: alloc::vec::Vec<ErgoBox> = tx
        .outs
        .iter()
        .enumerate()
        .map(|(i, h)| {
            let candidate = from_bytes(&hex(h))
                .with_versions(v3, v3, ErgoBoxCandidate::sigma_parse)
                .unwrap();
            ErgoBox::from_box_candidate(&candidate, tx_id, i as u16).unwrap()
        })
        .collect();
    let (self_box, in1, data) = (read_box(tx.self_box), read_box(tx.in1), read_box(tx.data));
    let (ext, ext1) = (read_ext(tx.ext), read_ext(tx.ext1));
    let mut ctx = force_any_val::<Context>();
    ctx.self_box = self_box;
    ctx.inputs = TxIoVec::from_vec(alloc::vec![self_box, in1]).unwrap();
    ctx.data_inputs = Some(TxIoVec::from_vec(alloc::vec![data]).unwrap());
    ctx.outputs = alloc::boxed::Box::leak(outs.into_boxed_slice());
    ctx.extension = leak(ext.clone());
    ctx.extension_provider = leak(DummyContextExtensionProvider(alloc::vec![ext, ext1]));
    ctx.activated_script_version_byte = 3;
    ctx
}

/// The rows whose outcome or cost counter is not the table's
#[allow(clippy::unwrap_used)]
fn wrong_rows(ctx: &Context<'static>, rows: &[Row]) -> alloc::vec::Vec<alloc::string::String> {
    let mut wrong = alloc::vec::Vec::new();
    for (name, body, version, expected, cost) in rows {
        let version = ErgoTreeVersion::from(*version);
        let bytes = base16::decode(body.as_bytes()).unwrap();
        let expr = from_bytes(&bytes)
            .with_tree_version(version, Expr::sigma_parse)
            .unwrap();
        ctx.tree_version.set(version);
        ctx.jit_cost.set(0);
        let res = expr.eval(&mut Env::empty(), ctx).map(|v| v.to_static());
        let stopped_at = ctx.jit_cost_value();
        let as_expected = match (&res, *expected) {
            (Ok(_), "VALUE") | (Err(_), "ERR") => true,
            (Ok(v), text) => jvm_text(v) == text,
            (Err(_), _) => false,
        };
        if !as_expected || stopped_at != *cost {
            wrong.push(alloc::format!(
                "{name}: expected {expected} at {cost}, got {res:?} at {stopped_at}"
            ));
        }
    }
    wrong
}

