#[test]
fn expression_collections() {
    let ctx = context(
        "050183020202010202028502010383010e83020202010202040e0201020583020101010100",
        "c0843d0008cd0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798640122222222222222222222222222222222222222222222222222222222222222220106830202020102028502018302010101010083010e83020202010202830204040204040e020102111111111111111111111111111111111111111111111111111111111111111100",
    );
    let wrong = wrong_rows(&ctx, EXPRESSION_COLLECTIONS);
    assert!(
        wrong.is_empty(),
        "{} of {} rows:\n{}",
        wrong.len(),
        EXPRESSION_COLLECTIONS.len(),
        wrong.join("\n")
    );
}

