#[test]
fn r1_keeps_the_tree_bytes() {
    let ctx = tx_context(&TxBytes {
        self_box: "c0843d00d19304820004026401222222222222222222222222222222222222222222222222222222222222222201068603830202020102020402040483011a83010e8302020201020283011983010d83020101010100830002860283020202010202040283020e830202020102020e020102111111111111111111111111111111111111111111111111111111111111111100",
        ext: "",
        in1: "c0843d00d1010164000183020202010202555555555555555555555555555555555555555555555555555555555555555500",
        ext1: "06018302020203020402860383020202010202040204040383011a83010e8302020201020206850201070e0203040983020101010100",
        data: "c0843d0008cd0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798640133333333333333333333333333333333333333333333333333333333333333330105830202020102028502018302010101010083010e830202020102020e020102444444444444444444444444444444444444444444444444444444444444444401",
        outs: &[
            "c0843d0008cd0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f817986401222222222222222222222222222222222222222222222222222222222222222201058302020201020285020183010e83020202010202860383020202010202040204040e020102",
            "c0843d00d10101640000",
        ],
        tx_id: "679937007aeb20a2394e4939331454e0389a98dca5a4ebecad8b6e91b1827c26",
    });
    let wrong = wrong_rows(&ctx, R1_KEEPS_THE_TREE_BYTES);
    assert!(
        wrong.is_empty(),
        "{} of {} rows:\n{}",
        wrong.len(),
        R1_KEEPS_THE_TREE_BYTES.len(),
        wrong.join("\n")
    );
}

