#[test]
fn pre_header() {
    let ctx = context(
        "02010e020102020d0201",
        "c0843d0008cd0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f817986401222222222222222222222222222222222222222222222222222222222222222201030e0201020d02011a0201010102111111111111111111111111111111111111111111111111111111111111111100",
    );
    let wrong = wrong_rows(&ctx, PRE_HEADER);
    assert!(
        wrong.is_empty(),
        "{} of {} rows:\n{}",
        wrong.len(),
        PRE_HEADER.len(),
        wrong.join("\n")
    );
}
